class EnergyHomePage extends StatefulWidget {
  const EnergyHomePage({Key? key}) : super(key: key);

  @override
  _EnergyHomePageState createState() => _EnergyHomePageState();
}

class _EnergyHomePageState extends State<EnergyHomePage> with SingleTickerProviderStateMixin {
  List<Map<String, dynamic>> dataPoints = [];
  bool isConnected = false;
  String connectionStatus = 'Disconnected';
  TabController? _tabController;
  Timer? _timer;
  final String esp32Ip = '192.168.4.1';

  @override
  void initState() {
    super.initState();
    _tabController = TabController(length: 3, vsync: this);
    _requestPermissions();
    _startFetchingData();
    // Optionally load weights from assets
    // _loadModelWeights();
  }

  // Optional: Load model weights from assets/model_weights.json
  Future<void> _loadModelWeights() async {
    try {
      final String jsonString = await DefaultAssetBundle.of(context).loadString('assets/model_weights.json');
      final Map<String, dynamic> weights = jsonDecode(jsonString);
      // Update global constants with loaded weights (requires dynamic assignment or state management)
      // For simplicity, hardcode weights as shown above
      print('Model weights loaded successfully');
    } catch (e) {
      print('Error loading model weights: $e');
    }
  }

  Future<void> _requestPermissions() async {
    Map<Permission, PermissionStatus> statuses = await [
      Permission.location,
    ].request();
    if (statuses[Permission.location]!.isDenied) {
      setState(() {
        connectionStatus = 'Location permission denied. Please grant it.';
      });
    }
  }

  Future<void> _fetchData() async {
    try {
      final response = await http.get(Uri.parse('http://$esp32Ip/')).timeout(const Duration(seconds: 5));
      if (response.statusCode == 200) {
        final data = jsonDecode(response.body);
        setState(() {
          isConnected = true;
          connectionStatus = 'Connected to ESP32';
          dataPoints.add(data);
          if (dataPoints.length > 50) dataPoints.removeAt(0);
        });
      } else {
        setState(() {
          isConnected = false;
          connectionStatus = 'Failed to fetch data: HTTP ${response.statusCode}';
        });
      }
    } catch (e) {
      setState(() {
        isConnected = false;
        connectionStatus = 'Connection error: $e';
      });
    }
  }

  void _startFetchingData() {
    _timer?.cancel();
    _timer = Timer.periodic(const Duration(seconds: 10), (timer) {
      _fetchData();
    });
  }

  void _stopFetchingData() {
    _timer?.cancel();
    setState(() {
      isConnected = false;
      connectionStatus = 'Disconnected';
      dataPoints.clear();
    });
  }

  @override
  void dispose() {
    _timer?.cancel();
    _tabController?.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      body: Container(
        decoration: BoxDecoration(
          gradient: LinearGradient(
            begin: Alignment.topCenter,
            end: Alignment.bottomCenter,
            colors: [const Color(0xFF0288D1), const Color(0xFF4FC3F7).withOpacity(0.8)],
          ),
        ),
        child: SafeArea(
          child: Column(
            children: [
              Container(
                padding: const EdgeInsets.symmetric(vertical: 16, horizontal: 20),
                child: Text(
                  'Energy Management System',
                  style: GoogleFonts.poppins(
                    fontSize: 28,
                    fontWeight: FontWeight.bold,
                    color: Colors.white,
                    shadows: [Shadow(color: Colors.black26, blurRadius: 4, offset: const Offset(2, 2))],
                  ),
                ),
              ).animate().fadeIn(duration: 600.ms).slideY(begin: -0.2, end: 0),
              Container(
                margin: const EdgeInsets.symmetric(horizontal: 16),
                decoration: BoxDecoration(
                  color: Colors.white,
                  borderRadius: BorderRadius.circular(12),
                  boxShadow: [
                    BoxShadow(
                      color: Colors.black12,
                      blurRadius: 10,
                      offset: const Offset(0, 4),
                    ),
                  ],
                ),
                child: TabBar(
                  controller: _tabController,
                  labelColor: const Color(0xFF0288D1),
                  unselectedLabelColor: Colors.grey,
                  indicatorColor: const Color(0xFFFFA726),
                  indicatorWeight: 4,
                  labelStyle: GoogleFonts.poppins(fontSize: 14, fontWeight: FontWeight.w600),
                  tabs: const [
                    Tab(icon: Icon(Icons.battery_charging_full_rounded), text: 'Charging'),
                    Tab(icon: Icon(Icons.battery_alert_rounded), text: 'Discharging'),
                    Tab(icon: Icon(Icons.analytics_rounded), text: 'Prediction'),
                  ],
                ),
              ).animate().fadeIn(duration: 800.ms).slideY(begin: -0.1, end: 0),
              Padding(
                padding: const EdgeInsets.all(12.0),
                child: Text(
                  connectionStatus,
                  style: GoogleFonts.poppins(
                    fontSize: 14,
                    color: isConnected ? Colors.green[700] : Colors.red[700],
                    fontWeight: FontWeight.w500,
                  ),
                ),
              ).animate().fadeIn(duration: 1000.ms),
              Expanded(
                child: TabBarView(
                  controller: _tabController,
                  children: [
                    ChargingTab(dataPoints: dataPoints),
                    DischargingTab(dataPoints: dataPoints),
                    PredictionTab(dataPoints: dataPoints),
                  ],
                ),
              ),
            ],
          ),
        ),
      ),
      floatingActionButton: FloatingActionButton(
        onPressed: isConnected ? _stopFetchingData : _startFetchingData,
        backgroundColor: isConnected ? const Color(0xFFFF5252) : const Color(0xFF0288D1),
        child: Icon(isConnected ? Icons.stop_rounded : Icons.play_arrow_rounded, size: 30),
        elevation: 6,
      ).animate().scale(duration: 600.ms, curve: Curves.easeInOut),
    );
  }
}

Widget _buildDataCard(String title, String value, String unit, IconData icon, Color color) {
  return Card(
    margin: const EdgeInsets.symmetric(vertical: 8),
    child: ListTile(
      leading: Icon(icon, size: 30, color: color),
      title: Text(
        title,
        style: GoogleFonts.poppins(fontSize: 16, fontWeight: FontWeight.w500),
      ),
      subtitle: Text(
        '$value $unit',
        style: GoogleFonts.poppins(fontSize: 14, color: Colors.grey[600]),
      ),
    ),
  ).animate().fadeIn(duration: 600.ms).slideX(begin: -0.1, end: 0);
}

Widget _buildLineChart(List<Map<String, dynamic>> dataPoints, String yKey, String? xKey, String yLabel, String xLabel, Color lineColor) {
  List<FlSpot> spots = [];
  for (int i = 0; i < dataPoints.length; i++) {
    final data = dataPoints[i];
    double? yValue = data[yKey]?.toDouble();
    double xValue = xKey != null ? data[xKey]?.toDouble() ?? i.toDouble() : i.toDouble();
    if (yValue != null) {
      spots.add(FlSpot(xValue, yValue));
    }
  }

  return Container(
    height: 250,
    padding: const EdgeInsets.all(16),
    child: LineChart(
      LineChartData(
        gridData: FlGridData(show: true, drawVerticalLine: false),
        titlesData: FlTitlesData(
          leftTitles: AxisTitles(
            sideTitles: SideTitles(
              showTitles: true,
              reservedSize: 40,
              getTitlesWidget: (value, meta) => Text(
                value.toStringAsFixed(1),
                style: GoogleFonts.poppins(fontSize: 12),
              ),
            ),
            axisNameWidget: Text(yLabel, style: GoogleFonts.poppins(fontSize: 14, color: Colors.white70)),
          ),
          bottomTitles: AxisTitles(
            sideTitles: SideTitles(
              showTitles: true,
              reservedSize: 30,
              getTitlesWidget: (value, meta) => Text(
                value.toInt().toString(),
                style: GoogleFonts.poppins(fontSize: 12),
              ),
            ),
            axisNameWidget: Text(xLabel, style: GoogleFonts.poppins(fontSize: 14, color: Colors.white70)),
          ),
          topTitles: AxisTitles(sideTitles: SideTitles(showTitles: false)),
          rightTitles: AxisTitles(sideTitles: SideTitles(showTitles: false)),
        ),
        borderData: FlBorderData(
          show: true,
          border: Border.all(color: Colors.white30, width: 1),
        ),
        lineBarsData: [
          LineChartBarData(
            spots: spots,
            isCurved: true,
            color: lineColor,
            barWidth: 3,
            dotData: FlDotData(show: false),
            belowBarData: BarAreaData(
              show: true,
              color: lineColor.withOpacity(0.2),
            ),
          ),
        ],
      ),
    ),
  );
}

