class PredictionTab extends StatefulWidget {
  final List<Map<String, dynamic>> dataPoints;
  const PredictionTab({Key? key, required this.dataPoints}) : super(key: key);

  @override
  _PredictionTabState createState() => _PredictionTabState();
}

class _PredictionTabState extends State<PredictionTab> {
  final TextEditingController _voltageController = TextEditingController();
  final TextEditingController _currentController = TextEditingController();
  String _predictionResult = 'Enter values to predict remaining time';
  bool _isLoading = false;

  void _predictRemainingTime() {
    setState(() {
      _isLoading = true;
    });

    try {
      double voltage = double.parse(_voltageController.text);
      double current = double.parse(_currentController.text);

      // Validate inputs
      if (voltage < 0 || voltage > 4.2) {
        setState(() {
          _predictionResult = 'Voltage must be between 0 and 4.2 V';
          _isLoading = false;
        });
        return;
      }
      if (current < 0.001 || current > 10) {
        setState(() {
          _predictionResult = 'Current must be between 0.001 and 10 A';
          _isLoading = false;
        });
        return;
      }

      // Predict using neural network
      double predictedTimeSeconds = BatteryMLP.forward(voltage, current);
      double predictedTimeHours = predictedTimeSeconds / 3600;

      setState(() {
        _predictionResult = 'Predicted remaining time: ${predictedTimeSeconds.toStringAsFixed(0)} seconds '
            '(${predictedTimeHours.toStringAsFixed(1)} hours)';
        _isLoading = false;
      });
    } catch (e) {
      setState(() {
        _predictionResult = 'Invalid input: Please enter numeric values';
        _isLoading = false;
      });
    }
  }

  @override
  void dispose() {
    _voltageController.dispose();
    _currentController.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final Map<String, dynamic> latestData = widget.dataPoints.isNotEmpty ? widget.dataPoints.last : {};
    return SingleChildScrollView(
      padding: const EdgeInsets.all(16.0),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Text(
            'Battery Life Prediction',
            style: GoogleFonts.poppins(
              fontSize: 22,
              fontWeight: FontWeight.bold,
              color: Colors.white,
              shadows: [Shadow(color: Colors.black26, blurRadius: 4, offset: const Offset(2, 2))],
            ),
          ).animate().fadeIn(duration: 600.ms),
          const SizedBox(height: 12),
          _buildDataCard('Latest Voltage', latestData['battery_V']?.toStringAsFixed(2) ?? 'N/A', 'V', Icons.bolt_rounded, Colors.orange[600]!),
          _buildDataCard('Latest Current', latestData['discharge_I_mA']?.toStringAsFixed(2) ?? 'N/A', 'mA', Icons.battery_alert_rounded, Colors.orange[600]!),
          const SizedBox(height: 20),
          Card(
            child: Padding(
              padding: const EdgeInsets.all(16.0),
              child: Column(
                children: [
                  TextField(
                    controller: _voltageController,
                    decoration: InputDecoration(
                      labelText: 'Enter Voltage (V)',
                      labelStyle: GoogleFonts.poppins(),
                      border: OutlineInputBorder(borderRadius: BorderRadius.circular(8)),
                    ),
                    keyboardType: TextInputType.number,
                  ).animate().fadeIn(duration: 800.ms),
                  const SizedBox(height: 12),
                  TextField(
                    controller: _currentController,
                    decoration: InputDecoration(
                      labelText: 'Enter Current (A)',
                      labelStyle: GoogleFonts.poppins(),
                      border: OutlineInputBorder(borderRadius: BorderRadius.circular(8)),
                    ),
                    keyboardType: TextInputType.number,
                  ).animate().fadeIn(duration: 1000.ms),
                  const SizedBox(height: 16),
                  _isLoading
                      ? const CircularProgressIndicator()
                      : ElevatedButton(
                          onPressed: _predictRemainingTime,
                          child: Text('Predict', style: GoogleFonts.poppins()),
                        ).animate().fadeIn(duration: 1200.ms),
                  const SizedBox(height: 16),
                  Text(
                    _predictionResult,
                    style: GoogleFonts.poppins(fontSize: 14, color: Colors.grey[800]),
                    textAlign: TextAlign.center,
                  ),
                ],
              ),
            ),
          ),
          const SizedBox(height: 20),
          Text(
            'Voltage vs Time',
            style: GoogleFonts.poppins(fontSize: 18, fontWeight: FontWeight.w600, color: Colors.white70),
          ).animate().fadeIn(duration: 1400.ms),
          _buildLineChart(widget.dataPoints, 'battery_V', null, 'Voltage (V)', 'Time (s)', Colors.orange[400]!),
        ],
      ),
    );
  }
}